  segs('data-tf', function (v) { tb.f = v; table(); });
  if (body) body.addEventListener('click', function (e) { var t = e.target.closest('tr[data-iso]'); if (t) { pick(t.getAttribute('data-iso')); var cp = document.getElementById('cc-pick'); if (cp) { cp.value = t.getAttribute('data-iso'); if (window.HHeco) window.HHeco.calc(); } } });
