    var xt = function (rot) { return Object.assign(axis({ grid: false }), { ticks: Object.assign({ autoSkip: false, maxRotation: narrow ? 45 : (rot || 0) }, tick) }); };
    function whisk(id, items, ctxfn) { return { id: 'wh-' + id, afterDatasetsDraw: function (ch) { var m = ch.getDatasetMeta(0), y = ch.scales.y, ctx = ch.ctx; ctx.save(); ctx.strokeStyle = INK; ctx.lineWidth = 1.5; m.data.forEach(function (b, i) { var it = items[i]; if (it.se === undefined) return; var lo = y.getPixelForValue(it.v - 1.96 * it.se), hi = y.getPixelForValue(it.v + 1.96 * it.se); ctx.beginPath(); ctx.moveTo(b.x, lo); ctx.lineTo(b.x, hi); ctx.moveTo(b.x - 5, lo); ctx.lineTo(b.x + 5, lo); ctx.moveTo(b.x - 5, hi); ctx.lineTo(b.x + 5, hi); ctx.stroke(); }); ctx.restore(); } }; }

