    HH.chart('chart-drag', {
      type: 'bar',
      data: { labels: IGS.map(function (g) { return IGN[g]; }), datasets: [{ label: 'Volatility drag (median σ²/2)', data: IGS.map(function (g) { return +med(C.filter(function (c) { return c.inc === g; }).map(function (c) { return c.drag; })).toFixed(3); }), backgroundColor: GREY, borderRadius: 2 }, { label: 'Growth lost to shortfalls (mean p × s)', data: IGS.map(function (g) { return +mean(C.filter(function (c) { return c.inc === g; }).map(function (c) { return c.ps; })).toFixed(2); }), backgroundColor: ORA, borderRadius: 2 }] },
      options: { layout: { padding: { top: 14 } }, plugins: { legend: legB, tooltip: { callbacks: { label: function (c) { return c.dataset.label + ': ' + fmt(c.raw, 2) + ' points a year'; } } } }, scales: { x: xt(), y: Object.assign(axis({ title: 'points of growth a year' }), { min: 0, ticks: tick }) } },
      plugins: [HH.valueLabels({ format: function (v) { return fmt(v, 2); } })]
    });
    var RM = [{ v: 0.046, se: 0.060, l: 'Mean growth, σ only' }, { v: 0.003, se: 0.056, l: 'Mean growth, + income' }, { v: 0.025, se: 0.045, l: 'Mean growth, + investment, schooling' }, { v: -0.038, se: 0.044, l: 'Compound growth, all controls' }, { v: -0.08, se: 0.043, l: 'Labour-productivity growth' }];
    HH.chart('chart-ramey', {
      type: 'bar',
      data: { labels: RM.map(function (r) { return r.l; }), datasets: [{ label: 'Coefficient on the standard deviation of growth', data: RM.map(function (r) { return r.v; }), backgroundColor: RM.map(function (r) { return Math.abs(r.v) > 1.96 * r.se ? ORA : alpha(GREY, 0.7); }), borderRadius: 2 }] },
      options: { indexAxis: 'x', layout: { padding: { top: 10 } }, plugins: { legend: { display: false }, tooltip: { callbacks: { label: function (c) { var r = RM[c.dataIndex]; return sg(r.v, 3) + ' (standard error ' + fmt(r.se, 3) + ')'; } } } }, scales: { x: Object.assign(xt(25), { ticks: Object.assign({ autoSkip: false, maxRotation: narrow ? 55 : 25, callback: function (v, i) { return RM[i].l; } }, tick, { font: { size: 10 } }) }), y: Object.assign(axis({ title: 'points of growth per point of σ' }), { min: -0.25, max: 0.25, ticks: tick }) } },
      plugins: [whisk('ram', RM)]
    });

